const tail = (s) => "</main>" + s + "</body></html>";

const hash = (p, s) => crypto.scryptSync(p, s, 32).toString("hex");
const eq = (a, b) => { a = Buffer.from(String(a)); b = Buffer.from(String(b)); return a.length === b.length && crypto.timingSafeEqual(a, b); };
function who(req) {
  const m = /(?:^|; )ses=([^;]+)/.exec(req.headers.cookie || "");
  if (!m || !SEC) return null;
  const p = m[1].split(".");
  if (p.length !== 3 || Date.now() > +p[1] || !eq(p[2], sign(p[0] + "." + p[1]))) return null;
  return p[0];
}
function setSes(res, w) {
  const e = Date.now() + 7 * 864e5;
  res.setHeader("Set-Cookie", "ses=" + w + "." + e + "." + sign(w + "." + e) + "; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=604800");
}
async function btcUsd() {
  try { const j = await (await fetch("https://mempool.space/api/v1/prices")).json(); if (j.USD) return +j.USD; } catch (e) {}
  const c = await (await fetch("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd")).json();
  return +c.bitcoin.usd;
}
// Auto-verify: LNURL verify URL first, then Blink's public status query
const tmo = () => AbortSignal.timeout(6000);
async function getJson(url) { const r = await fetch(url, { signal: tmo() }); if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); }
// Everything that was sent to BTC_ADDRESS, as one explorer sees it
async function chainFrom(base) {
  const tip = +(await getJson(base + "/blocks/tip/height"));
  if (!(tip > 0)) throw new Error("bad tip height");
  const out = [], seen = new Set();
  let page = await getJson(base + "/address/" + BTC_ADDRESS + "/txs"), pages = 0;
  for (;;) {
    for (const t of page) {
      if (seen.has(t.txid)) continue; seen.add(t.txid);
      const st = t.status || {};
      (t.vout || []).forEach((o, n) => {
        if (o.scriptpubkey_address === BTC_ADDRESS) out.push({ txid: t.txid, vout: n, sats: o.value, conf: st.confirmed ? Math.max(1, tip - st.block_height + 1) : 0, bt: st.confirmed ? st.block_time : 0 });
      });
    }
    const cf = page.filter((t) => t.status && t.status.confirmed), last = cf[cf.length - 1];
    if (cf.length < 25 || !last || ++pages >= 4 || last.status.block_time < Date.now() / 1000 - 4 * 3600) break;
    page = await getJson(base + "/address/" + BTC_ADDRESS + "/txs/chain/" + last.txid);
  }
  return out;
}
// Merged view: a payment only counts as deep as BOTH explorers confirm it. If either explorer fails -> null (unknown).
let chainBusy = null;
function chainState() {
  if (!chainBusy) chainBusy = chainLoad().finally(() => { chainBusy = null; });
  return chainBusy;
}
async function chainLoad() {
  try { const c = await db(["GET", "btc:cache"]); if (c) return JSON.parse(c); } catch (e) {}
  let res;
  try { res = await Promise.all(SOURCES.map((b) => chainFrom(b))); } catch (e) { return null; }
  const a = res[0], b = res[1], k = (o) => o.txid + ":" + o.vout, bm = new Map(b.map((o) => [k(o), o])), am = new Map(a.map((o) => [k(o), o])), out = [];
  for (const o of a) { const p = bm.get(k(o)); out.push(Object.assign({}, o, { conf: p && p.sats === o.sats ? Math.min(o.conf, p.conf) : 0, bt: p ? Math.max(o.bt, p.bt) : o.bt })); }
  for (const p of b) if (!am.has(k(p))) out.push(Object.assign({}, p, { conf: 0 }));
  try { await db(["SET", "btc:cache", JSON.stringify(out), "EX", 15]); } catch (e) {}
  return out;
}
const needOf = (r) => r.need || confsFor(r.usd);
async function settle(r, paid, extra) {
  if (paid) {
    if (await db(["SETNX", "paid:" + r.id, "1"])) {
      const c = Math.round(r.usd * 100); let fee = 0;
      if (r.owner !== "admin") {
        const x = await db(["HGET", "users", r.owner]);
        if (x) { fee = Math.round(c * (+JSON.parse(x).fee || 0) / 100); await db(["HINCRBY", "bal", r.owner, c - fee]); } else fee = c;
      }
      await db(["HINCRBY", "bal", "admin", r.owner === "admin" ? c : fee]);
    }
    if (extra) Object.assign(r, extra);
    r.st = "paid"; r.pt = Date.now();
  } else r.st = "expired";
  await db(["HSET", "inv", r.id, JSON.stringify(r)]);
}
// Matches payments to one invoice by the exact amount. ch === undefined -> load the chain; ch === null -> explorers down (do nothing).
async function checkOne(r, ch) {
  const chain = ch === undefined ? await chainState() : ch;
  if (!chain) return;
  const now = Date.now(), t0 = Math.floor(r.t / 1000) - 3600, t1 = Math.floor(r.exp / 1000) + 3600, n = needOf(r), lost = new Set();
  const hits = chain.filter((o) => o.sats === r.sats && (!o.bt || (o.bt >= t0 && o.bt <= t1))).sort((x, y) => y.conf - x.conf);
  for (const o of hits) {
    if (o.conf < n) continue;
    const key = "tx:" + o.txid + ":" + o.vout;
    if ((await db(["SET", key, r.id, "NX"])) || (await db(["GET", key])) === r.id) return settle(r, true, { tx: o.txid, vout: o.vout, recv: o.sats, conf: o.conf });
    lost.add(o);
  }
  const live = hits.filter((o) => !lost.has(o));
  if (live.length) { // payment seen, not deep enough yet
    const o = live[0];
    if (r.tx !== o.txid || r.conf !== o.conf) { r.tx = o.txid; r.conf = o.conf; await db(["HSET", "inv", r.id, JSON.stringify(r)]); }
    if (now > r.exp + 12 * 3600 * 1000) await settle(r, false);
    return;
  }
  if (now > r.exp) await settle(r, false);
}

