module.exports = async (req, res) => {
  const q = req.query || {};
  const path = "/" + [].concat(q.path || "").join("/");
  const json = (c, o) => { res.statusCode = c; res.setHeader("Content-Type", "application/json"); res.end(JSON.stringify(o)); };
  const html = (c, h) => { res.statusCode = c; res.setHeader("Content-Type", "text/html; charset=utf-8"); res.end(h); };
  const b = req.body || {};
  try {
    const mo = path.match(/^\/og\/([a-z0-9-]+)(?:\.png)?$/);
    if (mo) {
      const v = mo[1] === "main" ? JSON.stringify({ name: "Add funds", color: COLORS[0] }) : await db(["HGET", "links", mo[1]]);
      if (!v) return html(404, "Not found");
      const l = JSON.parse(v);
      let buf = null;
      if (!ogSupported(l.name)) try {
      const { ImageResponse } = await import("@vercel/og");
      const color = COLORS.includes(l.color) ? l.color : COLORS[0];
      const first = (l.name.match(/[A-Za-z0-9]/) || ["$"])[0].toUpperCase();
      const size = l.name.length <= 12 ? 150 : l.name.length <= 22 ? 110 : l.name.length <= 36 ? 80 : 60;
      const h = (type, style, children) => ({ type, props: { style, children } });
      const tree = h("div", { display: "flex", flexDirection: "column", justifyContent: "space-between", width: "100%", height: "100%", backgroundImage: "linear-gradient(135deg,#00E65A,#00C244)", padding: "64px", color: "#04130a" }, [
        h("div", { display: "flex", alignItems: "center" }, [
          h("div", { display: "flex", alignItems: "center", justifyContent: "center", width: 132, height: 132, borderRadius: 36, background: "#04130a", color: "#00E65A", fontSize: 92, fontWeight: 700 }, "$"),
          h("div", { display: "flex", flexDirection: "column", marginLeft: 32 }, [
            h("div", { display: "flex", fontSize: 50, fontWeight: 700 }, "Bitcoin Pay"),
            h("div", { display: "flex", fontSize: 32, fontWeight: 500 }, "Secure and instant")
          ])
        ]),
        h("div", { display: "flex", flexDirection: "column" }, [
          h("div", { display: "flex", fontSize: 46, fontWeight: 700, opacity: 0.7 }, "Pay"),
          h("div", { display: "flex", fontSize: size, fontWeight: 700, lineHeight: 1.05, letterSpacing: -3 }, l.name)
        ])
      ]);
      buf = Buffer.from(await new ImageResponse(tree, { width: 1200, height: 630 }).arrayBuffer());
      } catch (e) { buf = null; console.error("og image failed:", e && e.message); }
      if (!buf) { try { buf = ogRender(l.name); } catch (e) { buf = null; console.error("og render failed:", e && e.message); } }
      res.statusCode = 200;
      res.setHeader("Content-Type", "image/png");
      res.setHeader("Cache-Control", buf ? "public, max-age=3600, s-maxage=86400" : "public, max-age=300, s-maxage=300");
      return res.end(buf || OG_FALLBACK);
    }
    if (path === "/" || path === "/pay") return html(200, payPage("main", { name: "Add funds", note: "Pay with Bitcoin", color: COLORS[0], t: 1 }, req));
    if (path === "/admin") return html(200, ADMIN);
    const m = path.match(/^\/p\/([a-z0-9-]+)$/);
    if (m) {
      const v = await db(["HGET", "links", m[1]]);
      if (!v) return html(404, head("Not found") + "<h1>Link not found</h1>" + tail(""));
      return html(200, payPage(m[1], JSON.parse(v), req));
    }
    if (path === "/api/logout") { res.setHeader("Set-Cookie", "ses=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0"); return json(200, { ok: 1 }); }
    if (path === "/api/login" && req.method === "POST") {
      const u = String(b.username || "").trim().toLowerCase(), p = String(b.password || "");
      let ok = false, w = "admin";
      if (!u || u === "admin") ok = !!PW && eq(p, PW);
      else { const x = await db(["HGET", "users", u]); if (x) { const o = JSON.parse(x); ok = eq(hash(p, o.salt), o.hash); w = u; } }
      if (!ok) return json(401, { error: "Wrong username or password" });
      setSes(res, w); return json(200, { ok: 1 });
    }
    // ---- public: create invoice on the server (amount cannot be faked) ----
    if (path === "/api/invoice" && req.method === "POST") {
      const v = b.slug === "main" ? JSON.stringify({ name: "Add funds", owner: "admin" }) : await db(["HGET", "links", String(b.slug)]);
      const usd = Math.round(+b.usd * 100) / 100;
      if (!v || !(usd >= 1) || usd > 10000) return json(400, { error: "Enter an amount between $1 and $10,000." });
      if (!addrOk(BTC_ADDRESS)) return json(500, { error: "The Bitcoin address is not set up correctly." });
      const l = JSON.parse(v), price = await btcUsd(), t = Date.now();
      let sats = Math.round(usd / price * 1e8);
      if (sats < 1000) return json(400, { error: "That amount is too small for a Bitcoin payment." });
      // every recent invoice gets its own exact amount, so a payment can be matched to it
      const ids = (await db(["LRANGE", "ilog", 0, 149])) || [], used = new Set();
      const recent = ids.length ? ((await db(["HMGET", "inv", ...ids])) || []).filter(Boolean).map((x) => JSON.parse(x)) : [];
      for (const x of recent) if (x.sats && (x.st === "pending" || t - x.t < 6 * 3600 * 1000)) used.add(x.sats);
      for (let n = 0; used.has(sats) && n < 500; n++) sats += 1;
      if (used.has(sats)) return json(503, { error: "Too many open invoices. Please try again shortly." });
      const id = rand(12), btc = (sats / 1e8).toFixed(8);
      const rec = { id, slug: String(b.slug), name: l.name, owner: l.owner || "admin", usd, sats, btc, price, need: confsFor(usd), t, exp: t + INVOICE_MINUTES * 60 * 1000, st: "pending", conf: 0 };
      await db(["HSET", "inv", id, JSON.stringify(rec)]);
      await db(["LPUSH", "ilog", id]); await db(["LTRIM", "ilog", 0, 499]);
      return json(200, { id, addr: BTC_ADDRESS, sats, btc, price, exp: rec.exp, need: rec.need, uri: "bitcoin:" + BTC_ADDRESS + "?amount=" + btc });
    }
    // ---- public: payment check (the pay page asks every 10s) ----
    if (path === "/api/check") {
      const v = await db(["HGET", "inv", String(q.id || "")]);
      if (!v) return json(404, { error: "Not found" });
      const r = JSON.parse(v);
      if (r.st === "pending") await checkOne(r);
      return json(200, { st: r.st, usd: r.usd, conf: r.conf || 0, need: needOf(r), tx: r.tx || "" });
    }
    // ---- logged-in area ----
    const w = who(req);
    let me = w, urec = null;
    if (w && w !== "admin") { const x = await db(["HGET", "users", w]); if (x) urec = JSON.parse(x); else me = null; }
    if (!me) return json(401, { error: "Login required" });
    const admin = me === "admin";

    if (path === "/api/dash") {
      const ids = (await db(["LRANGE", "ilog", 0, 499])) || [];
      let inv = ids.length ? ((await db(["HMGET", "inv", ...ids])) || []).filter(Boolean).map((x) => JSON.parse(x)) : [];
      inv = inv.filter((x) => admin || x.owner === me);
      // match open invoices against the blockchain; invoices past their 2 hours with no payment become expired
      const nowT = Date.now(), pen = inv.filter((x) => x.st === "pending");
      const chain = admin || pen.length ? await chainState() : null;
      if (chain) await Promise.all(pen.slice(0, 100).map((x) => checkOne(x, chain)));
      let unm = [];
      if (admin && chain) { // payments to the address that no invoice has claimed
        const waiting = new Set(inv.filter((x) => x.st === "pending").map((x) => x.sats));
        const cand = chain.filter((o) => (!o.bt || o.bt > nowT / 1000 - 7 * 86400) && !waiting.has(o.sats));
        if (cand.length) { const cl = (await db(["MGET", ...cand.map((o) => "tx:" + o.txid + ":" + o.vout)])) || []; unm = cand.filter((o, i) => !cl[i]); }
      }
      const fl = (await db(["HGETALL", "links"])) || [], links = [];
      for (let i = 0; i < fl.length; i += 2) { const l = Object.assign({ slug: fl[i] }, JSON.parse(fl[i + 1])); if (!l.deleted && (admin || l.owner === me)) links.push(l); }
      links.sort((a, c) => c.t - a.t);
      const fb = (await db(["HGETALL", "bal"])) || [], bal = {};
      for (let i = 0; i < fb.length; i += 2) bal[fb[i]] = +fb[i + 1];
      const users = [];
      if (admin) { const fu = (await db(["HGETALL", "users"])) || []; for (let i = 0; i < fu.length; i += 2) { const o = JSON.parse(fu[i + 1]); users.push({ u: fu[i], fee: o.fee, pw: o.pw || "" }); } }
      const wids = (await db(["LRANGE", "wdlog", 0, 299])) || [];
      let wd = wids.length ? ((await db(["HMGET", "wd", ...wids])) || []).filter(Boolean).map((x) => JSON.parse(x)) : [];
      wd = wd.filter((x) => admin || x.u === me);
      return json(200, { me: { role: admin ? "admin" : "user", u: me, pw: admin ? PW : (urec && urec.pw) || "" }, bal: admin ? bal : { [me]: bal[me] || 0 }, users, links, inv, wd, unm, chain: !!chain });
    }
    if (path === "/api/withdraw" && req.method === "POST") {
      if (!admin) return json(403, { error: "Admin only" });
      const u = String(b.u || ""), cents = Math.round(parseFloat(b.usd) * 100);
      if (!(cents > 0) || cents > 1e9) return json(400, { error: "Enter a valid amount." });
      if (!(await db(["HGET", "users", u]))) return json(404, { error: "User not found" });
      const left = +(await db(["HINCRBY", "bal", u, -cents]));
      if (left < 0) { await db(["HINCRBY", "bal", u, cents]); return json(400, { error: "That is more than the unpaid balance." }); }
      const id = rand(12), rec = { id, u, amt: cents, t: Date.now() };
      await db(["HSET", "wd", id, JSON.stringify(rec)]); await db(["LPUSH", "wdlog", id]); await db(["LTRIM", "wdlog", 0, 999]);
      return json(200, { ok: 1, left });
    }
    if (path === "/api/withdraw/undo" && req.method === "POST") {
      if (!admin) return json(403, { error: "Admin only" });
      const id = String(b.id || ""), v = await db(["HGET", "wd", id]);
      if (!v) return json(404, { error: "Payment not found" });
      const r = JSON.parse(v);
      if (!(await db(["HGET", "users", r.u]))) return json(400, { error: "That user no longer exists." });
      if (!(await db(["HDEL", "wd", id]))) return json(404, { error: "Payment not found" });
      await db(["HINCRBY", "bal", r.u, r.amt]); await db(["LREM", "wdlog", 0, id]);
      return json(200, { ok: 1 });
    }
    if (path === "/api/btc/assign" && req.method === "POST") {
      if (!admin) return json(403, { error: "Admin only" });
      const chain = await chainState();
      if (!chain) return json(503, { error: "Cannot reach the blockchain explorers right now. Try again in a minute." });
      const o = chain.find((x) => x.txid === String(b.txid || "") && x.vout === +b.vout), v = await db(["HGET", "inv", String(b.id || "")]);
      if (!o) return json(404, { error: "Bitcoin payment not found." });
      if (!v) return json(404, { error: "Invoice not found. Copy the invoice ID from the Invoice column." });
      const r = JSON.parse(v);
      if (r.st === "paid") return json(400, { error: "That invoice is already paid." });
      if (o.conf < needOf(r)) return json(400, { error: "This payment has " + o.conf + " of " + needOf(r) + " confirmations. Try again later." });
      if (!(await db(["SET", "tx:" + o.txid + ":" + o.vout, r.id, "NX"]))) return json(400, { error: "This payment was already used for another invoice." });
      await settle(r, true, { tx: o.txid, vout: o.vout, recv: o.sats, conf: o.conf, manual: true });
      return json(200, { ok: 1 });
    }
    if (path === "/api/invoice/done" && req.method === "POST") {
      const v = await db(["HGET", "inv", String(b.id || "")]);
      if (!v) return json(404, { error: "Invoice not found" });
      const r = JSON.parse(v);
      if (!admin && r.owner !== me) return json(403, { error: "Not allowed" });
      r.done = !!b.done; r.dt = r.done ? Date.now() : 0;
      await db(["HSET", "inv", r.id, JSON.stringify(r)]);
      return json(200, { ok: 1, done: r.done });
    }
    if (path === "/api/users" && req.method === "POST") {
      if (!admin) return json(403, { error: "Admin only" });
      const u = String(b.username || "").trim().toLowerCase(), p = String(b.password || ""), fee = Math.min(50, Math.max(0, parseFloat(b.fee) || 0));
      if (!/^[a-z0-9_]{3,20}$/.test(u) || u === "admin") return json(400, { error: "Username: 3-20 letters, numbers or _ (not 'admin')." });
      if (p.length < 6) return json(400, { error: "Password needs at least 6 characters." });
      if (await db(["HGET", "users", u])) return json(400, { error: "That username already exists." });
      const salt = rand(16);
      await db(["HSET", "users", u, JSON.stringify({ salt, hash: hash(p, salt), pw: p, fee, t: Date.now() })]);
      return json(200, { ok: 1 });
    }
    if (path === "/api/users/password" && req.method === "POST") {
      if (!admin) return json(403, { error: "Admin only" });
      const u = String(b.u || ""), p = String(b.password || ""), x = await db(["HGET", "users", u]);
      if (!x) return json(404, { error: "User not found" });
      if (p.length < 6) return json(400, { error: "Password needs at least 6 characters." });
      const o = JSON.parse(x), salt = rand(16);
      await db(["HSET", "users", u, JSON.stringify(Object.assign(o, { salt, hash: hash(p, salt), pw: p }))]);
      return json(200, { ok: 1 });
    }
    if (path === "/api/users/delete" && req.method === "POST") {
      if (!admin) return json(403, { error: "Admin only" });
      if (!PW || !eq(String(b.password || ""), PW)) return json(403, { error: "Wrong admin password" });
      const u = String(b.u || "");
      await db(["HDEL", "users", u]); await db(["HDEL", "bal", u]);
      const fl = (await db(["HGETALL", "links"])) || [];
      for (let i = 0; i < fl.length; i += 2) { const lo = JSON.parse(fl[i + 1]); if (lo.owner === u && !lo.deleted) await db(["HSET", "links", fl[i], JSON.stringify(Object.assign(lo, { deleted: true, dt: Date.now() }))]); }
      return json(200, { ok: 1 });
    }
    if (path === "/api/links") {
      if (req.method === "POST") {
        const name = String(b.name || "").trim().slice(0, 60);
        if (!name) return json(400, { error: "Name is required" });
        const note = String(b.note || "").trim().slice(0, 100), color = COLORS.includes(b.color) ? b.color : COLORS[0];
        let slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || rand(6);
        if (slug === "main" || (await db(["HGET", "links", slug]))) slug += "-" + rand(4);
        await db(["HSET", "links", slug, JSON.stringify({ name, note, color, owner: me, t: Date.now() })]);
        return json(200, { slug });
      }
      if (req.method === "DELETE") {
        const s = String(q.slug || ""), v = await db(["HGET", "links", s]);
        if (v && (admin || JSON.parse(v).owner === me)) await db(["HSET", "links", s, JSON.stringify(Object.assign(JSON.parse(v), { deleted: true, dt: Date.now() }))]); // hidden from dashboard, saved link keeps working
        return json(200, { ok: 1 });
      }
    }
    return html(200, head("Payments") + "<h1>Payments</h1>" + tail(""));
  } catch (e) {
    return json(500, { error: "Server error: " + e.message });
  }
};
